import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();

  // Parse text content
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const quoteMarkContent = textItems.find(i => i.role === 'quote-mark')?.text ?? '"';
  const quoteContent = textItems.find(i => i.role === 'quote')?.text ?? '';
  const attributionContent = textItems.find(i => i.role === 'attribution')?.text ?? '';
  const captionContent = textItems.find(i => i.role === 'caption')?.text ?? '';

  // --- Panel dimensions ---
  const panelW = 3.4;
  const panelH = 1.9;
  const cornerR = 0.06;

  // Create rounded rect shape
  const shape = new ctx.THREE.Shape();
  const hw = panelW / 2;
  const hh = panelH / 2;
  shape.moveTo(-hw + cornerR, -hh);
  shape.lineTo(hw - cornerR, -hh);
  shape.quadraticCurveTo(hw, -hh, hw, -hh + cornerR);
  shape.lineTo(hw, hh - cornerR);
  shape.quadraticCurveTo(hw, hh, hw - cornerR, hh);
  shape.lineTo(-hw + cornerR, hh);
  shape.quadraticCurveTo(-hw, hh, -hw, hh - cornerR);
  shape.lineTo(-hw, -hh + cornerR);
  shape.quadraticCurveTo(-hw, -hh, -hw + cornerR, -hh);

  const panelGeo = new ctx.THREE.ShapeGeometry(shape);

  // Gradient color node
  const gradUv = uv();
  const c1 = color('#1a1a22');
  const c2 = color('#111116');
  const gradColor = mix(c1, c2, gradUv.y);

  const panelMat = new MeshStandardNodeMaterial({
    colorNode: gradColor,
    roughness: 0.6,
    metalness: 0.2,
    clearcoat: 0.1,
    transparent: true,
    opacity: 0,
  });

  const panel = new ctx.THREE.Mesh(panelGeo, panelMat);
  panel.position.z = -0.01;
  panel.position.y = -0.2; // start offset for animation
  group.add(panel);

  // --- Quotation mark ---
  const quoteMarkObj = ctx.fontAtlas.createText(quoteMarkContent, {
    fontSize: 62,
    color: '#ff2a38',
    align: 'left',
  });

  // Replace material for 3D appearance
  quoteMarkObj.traverse((child) => {
    if (child.isMesh) {
      child.material = new MeshStandardNodeMaterial({
        color: '#ff2a38',
        roughness: 0.5,
        metalness: 0.3,
      });
    }
  });

  // Position: top-left padding 0.5 units
  const markX = -panelW / 2 + 0.5;
  const markY = panelH / 2 - 0.5 - 0.62; // 0.62 height assumed, baseline adjust
  quoteMarkObj.position.set(markX, markY, 0.02);
  quoteMarkObj.scale.set(1.04, 1.04, 1.04); // overshoot start
  group.add(quoteMarkObj);

  // --- Quote text ---
  const quoteObj = ctx.fontAtlas.createText(quoteContent, {
    fontSize: 20,
    color: '#e8ecf2',
    align: 'left',
    maxWidthPx: 240, // approx 2.4 scene units at 100px/unit
  });
  const quoteY = markY - 0.62 - 0.25; // 0.25 below quote mark bottom
  quoteObj.position.set(markX, quoteY, 0.03);
  quoteObj.traverse((child) => {
    if (child.isMesh) {
      child.material.transparent = true;
      child.material.opacity = 0;
    }
  });
  group.add(quoteObj);

  // --- Accent rule ---
  const ruleGeo = new ctx.THREE.PlaneGeometry(0.2, 0.02);
  const ruleMat = new MeshStandardNodeMaterial({
    color: '#ff2a38',
    emissive: '#ff2a38',
    emissiveIntensity: 1.4,
    transparent: true,
    opacity: 0,
  });
  const rule = new ctx.THREE.Mesh(ruleGeo, ruleMat);
  const ruleY = quoteY - 0.25;
  rule.position.set(markX, ruleY, 0.03);
  group.add(rule);

  // --- Attribution ---
  const attribObj = ctx.fontAtlas.createText(attributionContent, {
    fontSize: 13,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 0.08 * 13,
  });
  const attribX = markX + 0.2 + 0.15;
  attribObj.position.set(attribX, ruleY, 0.03);
  attribObj.traverse((child) => {
    if (child.isMesh) {
      child.material.transparent = true;
      child.material.opacity = 0;
    }
  });
  group.add(attribObj);

  // --- Caption ---
  const captionObj = ctx.fontAtlas.createText(captionContent, {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 0.12 * 9,
  });
  const captionY = ruleY - 0.25;
  captionObj.position.set(markX, captionY, 0.03);
  captionObj.traverse((child) => {
    if (child.isMesh) {
      child.material.transparent = true;
      child.material.opacity = 0;
    }
  });
  group.add(captionObj);

  // --- Animations ---
  const tl = gsap.timeline();

  // Panel fade-up + rise
  tl.to(panel.position, { y: 0, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }, 0);
  tl.to(panelMat, { opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }, 0);

  // Quote mark weighted settle (starts after panel arrives)
  tl.to(quoteMarkObj.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'cubic-bezier(0.165,0.84,0.44,1)',
  }, 0.5);

  // Fade in quote, rule, attribution, caption
  const fadeTargets = [quoteObj, rule, attribObj, captionObj];
  fadeTargets.forEach(obj => {
    obj.traverse((child) => {
      if (child.isMesh) {
        tl.to(child.material, { opacity: 1, duration: 0.4, ease: 'power2.out' }, 0.5);
      }
    });
  });

  // --- Handlers ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    tl.kill();
    panelGeo.dispose();
    panelMat.dispose();
    ruleGeo.dispose();
    ruleMat.dispose();
    // Dispose all children recursively
    group.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose();
        child.material?.dispose();
      }
    });
    while (group.children.length) {
      group.remove(group.children[0]);
    }
  };

  return group;
}
